import{z as l,x as B,o as t,c as A,q as s,j as n,D as r,d as p,s as o,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"PBFT","description":"","frontmatter":{"title":"PBFT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pbft.md","filePath":"cs/pbft.md","lastUpdated":1791413859000}'),f={name:"cs/pbft.md"};function d(m,a,F,C,P,c){const i=B("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="pbft" tabindex="-1">PBFT <a class="header-anchor" href="#pbft" aria-label="Permalink to &quot;PBFT&quot;">​</a></h1><div class="epigraph"><p>部分同步下用 $n=3f+1$ 做拜占庭状态机：预准备、准备、提交三阶段，证书交叉验证，视图更换换主。</p><footer>—— 据 Castro and Liskov, Practical Byzantine Fault Tolerance, OSDI 1999 整理</footer></div><p>上一课<a href="/cs/viewstamped-replication">VR</a>的视图更换假定备份只崩溃或慢。缺口是<strong>备份撒谎</strong>：准备证书必须防伪造、防分裂。本课接<a href="/cs/byzantine-generals">拜占庭将军</a>的 \\(n\\gt 3f\\)，时间用部分同步，不把口头 OM 递归再写一遍。后课对照 2PC：2PC 连崩溃协调者都堵，更不抗撒谎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主（primary）在视图里给请求编号并广播 pre-prepare。备份验证后广播 prepare。收集 \\(2f\\) 个匹配 prepare（加自己）形成 prepared 证书——保证诚实节点对「这个序号是这个请求」有交集。再广播 commit，收集 \\(2f+1\\) 个 commit 后执行。三阶段让诚实节点在执行前对请求与序号有法定人数交叉。</p><p><span class="marginnote">数字实例：\\(f=1\\) 时 \\(n=3f+1=4\\) 个副本——容忍 1 个撒谎；prepare 证书要 \\(2f=2\\) 个匹配加自己，commit 要 \\(2f+1=3\\) 个。\\(f=2\\) 时就要 7 个副本。副本数随容错数线性涨、通信还按平方涨，这正是 PBFT 适合小规模委员会而不是几千节点的原因。</span></p><p>主坏：备份超时触发 view change，新主带着 prepared 证书证明必须带着走的请求，避免分叉执行。</p><p><span class="marginnote">OSDI 1999 强调实用：MAC 而不是每次数字签名、垃圾回收、窗口。安全在异步下保持，活靠部分同步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>认证信道：点对点 MAC 或签名。摘要链减少载荷。状态检查点做垃圾回收，类似快照但要证书证明检查点合法。客户端自己收集 \\(f+1\\) 个相同应答才接受——因为主可能对客户端撒谎。</p><p><span class="marginnote">为什么客户端要 \\(f+1\\) 份相同应答：最多 \\(f\\) 个节点会撒谎，收到 \\(f+1\\) 份一模一样的结果时，其中至少 1 份出自诚实节点，而诚实节点只在证书齐了之后才执行——于是这个结果必是「真相」而非伪造。1 份都不够信：那可能正是主单方面编的。</span></p>',11)),(t(),n(E,null,{default:r(()=>[o(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PP%5B%22pre-prepare%22%5D%20--%3E%20P%5B%22prepare%20%E8%AF%81%E4%B9%A6%22%5D%0A%20%20P%20--%3E%20C%5B%22commit%20%E8%AF%81%E4%B9%A6%22%5D%0A%20%20C%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%22%5D%0A%20%20TO%5B%22%E8%B6%85%E6%97%B6%22%5D%20--%3E%20VC%5B%22view%20change%22%5D%0A%20%20VC%20--%3E%20PP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Raft：多了撒谎，法定人数从 \\(f+1\\) 变成 \\(2f+1\\) 这一档（\\(n=3f+1\\)）。不能用「多数派心跳」当正确性。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[p("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"prepared 证书相交：两个不同请求不能在同一序号都达到 prepared（诚实节点不协助）。commit 让节点知道「足够多诚实者已 prepared」，于是执行后崩溃恢复仍能证明。这比崩溃 Paxos 多一轮，税来自拜占庭。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为拜占庭容错只是「多备几台」。实际上代价是三件套：副本从 \\(2f+1\\) 涨到 \\(3f+1\\)（崩溃容忍 3 台的事这里要 4 台）、每步法定人数翻倍（\\(f+1\\) 变 \\(2f+1\\)）、外加一轮通信与认证开销——「税」买的是对面会主动撒谎这种最强敌手模型。")],-1)),(t(),n(E,null,{default:r(()=>[o(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%7B%22%E6%95%8C%E6%89%8B%E6%A8%A1%E5%9E%8B%EF%BC%9F%22%7D%0A%20%20CMP%20--%20%22%E5%8F%AA%E4%BC%9A%E5%B4%A9%E6%BA%83%22%20--%3E%20CF%5B%22Raft%20%2F%20Paxos%EF%BC%9An%20%3D%202f%2B1%22%5D%0A%20%20CF%20--%3E%20CF2%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%20f%2B1%20%E5%8D%B3%E5%8F%AF%E6%8F%90%E4%BA%A4%22%5D%0A%20%20CMP%20--%20%22%E4%BC%9A%E6%92%92%E8%B0%8E%22%20--%3E%20BF%5B%22PBFT%EF%BC%9An%20%3D%203f%2B1%22%5D%0A%20%20BF%20--%3E%20BF2%5B%22prepare%20%E8%AF%81%E4%B9%A6%202f%EF%BC%8Ccommit%20%E8%AF%81%E4%B9%A6%202f%2B1%22%5D%0A%20%20BF2%20--%3E%20BF3%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%86%8D%E6%94%B6%20f%2B1%20%E4%BB%BD%E7%9B%B8%E5%90%8C%E5%BA%94%E7%AD%94%22%5D%0A%20%20CF2%20--%3E%20OUT%5B%22%E5%A4%9A%E5%87%BA%E7%9A%84%E5%89%AF%E6%9C%AC%E4%B8%8E%E8%BD%AE%E6%AC%A1%EF%BC%9A%E6%8B%9C%E5%8D%A0%E5%BA%AD%E7%A8%8E%22%5D%0A%20%20BF3%20--%3E%20OUT%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[p(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><a href="/cs/flp-impossibility">FLP</a>仍在：异步下 view change 可能永远抖。随机与超时是活性。恶意主可以在被换掉前拖延迟，但不能让两个诚实节点提交不同的同一序号请求。</p><p>本课不把比特币当 PBFT。也不写 BFT-SMaRt 的全部优化。权益与委员会是后课 PoW 直觉的对照对象，不是 PBFT 本身。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证全部不变量，不引入异步 BFT 的心跳复杂度下界细节。后课默认：崩溃 RSM 用 Raft/Paxos；\\(f\\) 撒谎用 \\(3f+1\\) 与三阶段。下一课把共识与两阶段提交的阻塞差讲清，避免把协调者当法定人数。</p><p>交叉证书替代「信任主」。主只是性能优化，不是信任根。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PBFT：\\(n=3f+1\\)，pre-prepare / prepare / commit。</li><li>安全异步；视图更换给活性。</li><li>客户端收 \\(f+1\\) 份相同应答。</li><li>出处：Castro and Liskov, OSDI 1999。</li></ul>',7))])}const h=l(f,[["render",d]]);export{T as __pageData,h as default};
